input.sparql:
SELECT ?point ?ts ?uri WHERE {
  ?ahu a brick:AirHandlingUnit ; brick:hasTag "AHU02" .
  ?point brick:isPointOf ?ahu .
  ?point a brick:ElectricPower .
  ?point ref:hasTimeseriesId ?ts .
  OPTIONAL { ?point ref:hasExternalReference ?uri }
}

SELECT ?ahu WHERE {
  ?ahu a brick:AirHandlingUnit .
  ?ahu brick:hasTag ?t .
  FILTER (contains(str(?t), "AHU02") || contains(str(?t), "ahu02"))
}

SELECT ?point ?ts WHERE {
  ?point a brick:ElectricPower ; brick:isPointOf ?ahu .
  FILTER (str(?ahu) ENDS WITH "AHU02")
  ?point ref:hasExternalReference ?tsref .
  ?tsref ref:hasTimeseriesId ?ts
}

SELECT ?point ?ts WHERE {
  ?point a brick:ElectricPower .
  ?point ref:hasExternalReference ?tsref .
  ?tsref ref:hasTimeseriesId ?ts
}

